import{_ as e,o as t,c as i,a2 as n}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Meditation & Concentration","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/magic/meditation-and-concentration.md","filePath":"en/guide/magic/meditation-and-concentration.md"}'),r={name:"en/guide/magic/meditation-and-concentration.md"};function o(d,a,s,l,c,m){return t(),i("div",null,[...a[0]||(a[0]=[n('<h1 id="meditation-concentration" tabindex="-1">Meditation &amp; Concentration <a class="header-anchor" href="#meditation-concentration" aria-label="Permalink to &quot;Meditation &amp; Concentration&quot;">​</a></h1><p><strong>Status:</strong> Proposed · Availability not established.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Meditation concerns recovery, organization and preparation.</li><li><a href="/Syrolands-Public/en/guide/glossary.html#concentration">Concentration</a> means stability under pressure, not automatically another capped <a href="/Syrolands-Public/en/guide/characters/skills.html">skill</a>.</li><li>Failing to execute a spell and having a cast interrupted are different events.</li></ul><p><span id="meditation-and-concentration"></span><span id="at-a-glance"></span></p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Player meaning</th></tr></thead><tbody><tr><td>Meditation</td><td>May help arrange <a href="/Syrolands-Public/en/guide/magic/memory-and-familiarity.html">Active Memory</a>, prepare difficult patterns and recover readiness.</td></tr><tr><td>Concentration</td><td>May be challenged by damage, movement, <a href="/Syrolands-Public/en/guide/glossary.html#fatigue">fatigue</a>, trauma and complex casts.</td></tr><tr><td>Fizzle</td><td>The magical structure is not executed correctly.</td></tr><tr><td>Interruption</td><td>Pressure disrupts an attempted cast. Exact costs for both outcomes remain open.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Compared with classic UO <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Permalink to &quot;Compared with classic UO&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classic UO</th><th>Syrolands direction</th></tr></thead><tbody><tr><td>Meditation supports mana regeneration, actively and passively.</td><td>Also explore mental organization, preparation and recovery of readiness.</td></tr><tr><td>Casting already involves success checks and interruption concerns.</td><td>Keep execution failure distinct from stability under pressure and localized injury.</td></tr></tbody></table><p>UO rules vary by era and shard. <a href="https://uo.com/wiki/ultima-online-wiki/skills/magery/" target="_blank" rel="noreferrer">Official UO: Magery and Meditation</a>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>A mage with plenty of mana may still struggle under repeated pressure. Finding breathing room could matter as much as restoring resources before attempting a difficult pattern.</p><h2 id="progression-trade-offs" tabindex="-1">Progression / trade-offs <a class="header-anchor" href="#progression-trade-offs" aria-label="Permalink to &quot;Progression / trade-offs&quot;">​</a></h2><p>Learned mental states should involve commitments and trade-offs. No trance list, free combat swap, numeric bonus or interruption formula is finalized.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/magic/memory-and-familiarity.html">Memory</a> · <a href="/Syrolands-Public/en/guide/magic/overview.html">Magery</a> · <a href="/Syrolands-Public/en/guide/combat/stamina-and-reactive-combat.html">Stamina and Flow</a></p><h2 id="full-design-specification" tabindex="-1">Full design specification <a class="header-anchor" href="#full-design-specification" aria-label="Permalink to &quot;Full design specification&quot;">​</a></h2><p>Read the <a href="/Syrolands-Public/en/game-design/magic.html#meditation-and-concentration">Meditation &amp; Concentration</a> design specification.</p>',18)])])}const p=e(r,[["render",o]]);export{u as __pageData,p as default};
